#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;
​
vector<string> map = {"abc", "def", "ghi", "jkl", "mno", "pqr", "st", "uv", "wx", "yz"};
unordered_set<char> filterSet;
​
bool isContainsAllFilterChars(unordered_set<char>& used) {
    for (auto x : filterSet) {
        if (used.find(x) == used.end()) {
            return true;
        }
    }
    return false;
}
​
​
void dfs(vector<string>& letters, int index, string path, string& res, string& filter, unordered_set<char>& used) {
    if (index == letters.size()) {
        if (isContainsAllFilterChars(used)) {
            res += path + ",";
        }
        return;
    }
​
    // 对于每个数字，遍历其对应的字母字符串
    for (int i = 0; i < letters[index].length(); i++) {
        char c = letters[index][i];
        // 递归回溯
        path += c;
        used.insert(c);
        dfs(letters, index + 1, path, res, filter, used);
        path.pop_back();
        used.erase(c);
    }
}
​
int main() {
    string digits;
    cin >> digits;
    string filter;
    cin >> filter;

    for (int i = 0; i < filter.size(); i++) {
        filterSet.insert(filter[i]);
    }
​
    // 根据数字字符串得到每个数字对应的字母字符串
    vector<string> letters(digits.length());
    for (int i = 0; i < digits.length(); i++) {
        letters[i] = map[digits[i] - '0'];
    }
​
    // 用于存储结果的字符串
    string res = "";
    // 开始进行深度优先搜索
    unordered_set<char> used;
    dfs(letters, 0, "", res, filter, used);
​
    // 输出结果
    cout << res << endl;
​
    return 0;
}

