package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
var charMap = []string{"abc", "def", "ghi", "jkl", "mno", "pqr", "st", "uv", "wx", "yz"}
var filterSet map[rune]struct{}
​
// 判断是否包含所有过滤字符
func isContainsAllFilterChars(used map[rune]struct{}) bool {
    for x := range filterSet {
        if _, exists := used[x]; !exists {
            return true
        }
    }
    return false
}
​
// 递归回溯
func dfs(letters []string, index int, path []rune, res *[]string, used map[rune]struct{}) {
    if index == len(letters) {
        if isContainsAllFilterChars(used) {
            *res = append(*res, string(path)+",")
        }
        return
    }
​
    // 遍历当前数字对应的字母
    for _, c := range letters[index] {
        path = append(path, c)
        used[c] = struct{}{}
        dfs(letters, index+1, path, res, used)
        path = path[:len(path)-1]
        delete(used, c)
    }
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    // 读取数字字符串
    scanner.Scan()
    digits := scanner.Text()
​
    // 读取过滤字符
    scanner.Scan()
    filter := scanner.Text()
​
    // 记录需要筛选的字符
    filterSet = make(map[rune]struct{})
    for _, c := range filter {
        filterSet[c] = struct{}{}
    }
​
    // 获取对应的字母映射
    letters := make([]string, len(digits))
    for i, c := range digits {
        letters[i] = charMap[c-'0']
    }
​
    // 结果存储
    var res []string
    dfs(letters, 0, []rune{}, &res, make(map[rune]struct{}))
​
    // 输出结果
    fmt.Println(strings.Join(res, ""))
}
